using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.IMGUI.Controls;
[CustomEditor(typeof(TrainingSpatialAuthoring))]public sealed class TrainingSpatialAuthoringInspector:Editor {
 void OnEnable(){Undo.undoRedoPerformed+=RefreshUndo;}void OnDisable(){Undo.undoRedoPerformed-=RefreshUndo;}void RefreshUndo(){if(target!=null)((TrainingSpatialAuthoring)target).Refresh();}
 string status="Draft only until Save SO";BoxBoundsHandle box=new BoxBoundsHandle();
 public override void OnInspectorGUI(){var a=(TrainingSpatialAuthoring)target;if(Application.isPlaying){EditorGUILayout.HelpBox("Edit outside Play",MessageType.Info);return;}if(a.draft==null)a.Reload();EditorGUI.BeginChangeCheck();var kind=(TrainingSpatialAuthoring.ActionKind)EditorGUILayout.EnumPopup("Action context",a.action);if(kind!=a.action){a.action=kind;a.command=a.Choices.FirstOrDefault();a.frame=0;a.Reload();}var choices=a.Choices;int selected=System.Array.IndexOf(choices,a.command);var choice=EditorGUILayout.Popup("Move",Mathf.Max(0,selected),choices.Select(c=>c.ToString()).ToArray());var command=choices.Length>0?choices[choice]:a.command;if(EditorGUI.EndChangeCheck()){a.command=command;a.frame=0;a.Reload();}if(a.Move==null){EditorGUILayout.HelpBox("No existing action data. No new move is created.",MessageType.Info);return;}a.editTarget=(TrainingSpatialAuthoring.EditTarget)EditorGUILayout.EnumPopup("Scene edit target",a.editTarget);if(a.editTarget==TrainingSpatialAuthoring.EditTarget.HurtBox&&a.draft.keys[0].hurt.Length>0)a.hurtIndex=EditorGUILayout.Popup("Hurt part",Mathf.Clamp(a.hurtIndex,0,a.draft.keys[0].hurt.Length-1),a.draft.keys[0].hurt.Select(h=>"Part ID "+h.partId).ToArray());EditorGUILayout.LabelField("Switching action discards unsaved draft; Save SO is explicit.");EditorGUI.BeginChangeCheck();a.frame=EditorGUILayout.Slider("Frame (60Hz)",a.frame,0,a.Move.Duration*60);EditorGUILayout.BeginHorizontal();if(GUILayout.Button("-1 F")){a.frame=Mathf.Max(0,a.frame-1);a.Refresh();}if(GUILayout.Button("+1 F")){a.frame=Mathf.Min(a.Move.Duration*60,a.frame+1);a.Refresh();}EditorGUILayout.EndHorizontal();EditorGUILayout.LabelField("Phase",a.frame<a.Move.startupFrames?"Startup":a.frame<a.Move.startupFrames+a.Move.activeFrames?"Active":"Recovery");a.facing=EditorGUILayout.Toggle("Mirror left",a.facing<0)?-1:1;if(EditorGUI.EndChangeCheck())a.Refresh();EditorGUILayout.LabelField("Keys",string.Join(", ",a.draft.keys.Select(k=>k.frame.ToString("0.##"))));if(GUILayout.Button("Capture sampled frame as key")){var k=a.draft.Sample(a.frame);a.Put(k);}if(GUILayout.Button("Save authoritative SO"))status=a.Save();if(GUILayout.Button("Cancel draft / reload SO")){a.Reload();status="Reloaded SO; unsaved edits discarded";}EditorGUILayout.HelpBox(status+"\nScene handles: white = body travel, cyan = sprite offset, red = attack, green = hurt. Meters; forward flips with facing. Body controller is never edited here.",MessageType.Info);}
 void OnSceneGUI(){
  var a=(TrainingSpatialAuthoring)target;if(Application.isPlaying||a.draft==null||a.Move==null)return;var k=a.draft.Sample(a.frame);if(k==null)return;
  var origin=a.transform.position;var body=origin+Vector3.right*k.rootForward*a.facing;EditorGUI.BeginChangeCheck();Handles.color=Color.white;Handles.Label(body,"BODY horizontal travel (XY)");
  var nextBody=a.editTarget==TrainingSpatialAuthoring.EditTarget.All||a.editTarget==TrainingSpatialAuthoring.EditTarget.Body?Handles.Slider(body,Vector3.right):body;k.rootForward=(nextBody.x-origin.x)*a.facing;body=origin+Vector3.right*k.rootForward*a.facing;
  Handles.color=Color.cyan;var sprite=body+(Vector3)TrainingCoordinates2D.FromLegacy(k.visualOffset,a.facing);Handles.Label(sprite+Vector3.up*.2f,"SPRITE offset");
  var nextSprite=a.editTarget==TrainingSpatialAuthoring.EditTarget.All||a.editTarget==TrainingSpatialAuthoring.EditTarget.Sprite?Handles.PositionHandle(sprite+Vector3.up*.2f,Quaternion.identity)-Vector3.up*.2f:sprite;
  k.visualOffset=TrainingCoordinates2D.ToLegacy((Vector2)(nextSprite-body),k.visualOffset.x,a.facing);
  using(new Handles.DrawingScope(Matrix4x4.TRS(body,Quaternion.identity,new Vector3(a.facing,1,1)))){
   box.axes=PrimitiveBoundsHandle.Axes.X|PrimitiveBoundsHandle.Axes.Y;box.center=TrainingCoordinates2D.FromLegacy(k.hitCenter);box.size=(Vector3)(TrainingCoordinates2D.HalfSize(k.hitHalfSize)*2);box.SetColor(Color.red);
   if(a.editTarget==TrainingSpatialAuthoring.EditTarget.All||a.editTarget==TrainingSpatialAuthoring.EditTarget.HitBox)box.DrawHandle();
   k.hitCenter=TrainingCoordinates2D.ToLegacy(box.center,k.hitCenter.x);k.hitHalfSize=TrainingCoordinates2D.ToLegacy((Vector2)box.size*.5f,k.hitHalfSize.x);
   foreach(var h in k.hurt){if(a.editTarget!=TrainingSpatialAuthoring.EditTarget.All&&(a.editTarget!=TrainingSpatialAuthoring.EditTarget.HurtBox||h!=k.hurt[Mathf.Clamp(a.hurtIndex,0,k.hurt.Length-1)]))continue;box.center=TrainingCoordinates2D.FromLegacy(h.center);box.size=TrainingCoordinates2D.HalfSize(h.size);box.SetColor(Color.green);box.DrawHandle();h.center=TrainingCoordinates2D.ToLegacy(box.center,h.center.x);h.size=TrainingCoordinates2D.ToLegacy(box.size,h.size.x);}
  }
  if(EditorGUI.EndChangeCheck()){k.frame=a.frame;a.Put(k);Repaint();}
 }

}
